//! Versioned, evaluated knowledge and opt-in semantic incident contributions.
//! The sharing schema has no messages, names, event references, dates or notes.
//! Public origin/episode IDs are random receipts generated by the exporter.
use crate::*;
use serde::{Deserialize, Serialize};
use std::collections::{BTreeMap, BTreeSet};

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DiagnosticLabel {
    pub diagnosis: Diagnosis,
    pub confirmed: bool,
}
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DiagnosticContribution {
    pub schema_version: u32,
    pub id: String,
    pub origin: String,
    pub episode: String,
    pub revision: u64,
    pub features: u64,
    pub scores: BTreeMap<Diagnosis, u16>,
    pub labels: Vec<DiagnosticLabel>,
}
impl DiagnosticContribution {
    pub fn seal(&mut self) {
        self.labels.sort_by_key(|l| l.diagnosis);
        self.id.clear();
        self.id = digest(&serde_json::to_vec(self).expect("finite semantic protocol"));
    }
    pub fn validate(&self) -> Result<(), String> {
        let receipt = |v: &str| v.len() == 32 && v.bytes().all(|b| b.is_ascii_hexdigit());
        if self.schema_version != DIAGNOSTIC_SCHEMA
            || !receipt(&self.origin)
            || !receipt(&self.episode)
            || self.revision == 0
            || self.revision > 1_000_000_000
            || !valid_feature_mask(self.features)
            // An empty, zero-feature receipt explicitly retracts prior labels.
            || (self.labels.is_empty() && (self.features != 0 || !self.scores.is_empty()))
            || self.labels.len() > 14
            || self.scores.len() > 14
            || self.scores.values().any(|s| *s > 85)
            || self
                .labels
                .iter()
                .map(|l| l.diagnosis)
                .collect::<BTreeSet<_>>()
                .len()
                != self.labels.len()
        {
            return Err("Contribuição diagnóstica fora do esquema fechado ou orçamento".into());
        }
        let mut sealed = self.clone();
        sealed.seal();
        if sealed.id != self.id {
            return Err("Identidade da contribuição diagnóstica diverge do conteúdo".into());
        }
        Ok(())
    }
}
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DiagnosticContributionBundle {
    pub schema_version: u32,
    pub contributions: Vec<DiagnosticContribution>,
}
impl DiagnosticContributionBundle {
    pub fn validate(&self) -> Result<(), String> {
        if self.schema_version != DIAGNOSTIC_SCHEMA || self.contributions.len() > 256 {
            return Err("Pacote diagnóstico excedeu 256 contribuições".into());
        }
        let mut ids = BTreeSet::new();
        for c in &self.contributions {
            c.validate()?;
            if !ids.insert(&c.id) {
                return Err("Contribuição diagnóstica repetida".into());
            }
        }
        Ok(())
    }
}
#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DiagnosticEvaluationCase {
    pub id: String,
    pub origin: String,
    pub split: String,
    pub expected: Option<Diagnosis>,
    pub records: Vec<DiagnosticRecord>,
    #[serde(default)]
    pub derived_features: Vec<DiagnosticFeature>,
}
#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DiagnosticEvaluationCount {
    pub cases: u64,
    pub eligible: u64,
    pub top_one: u64,
    pub top_three: u64,
    pub false_diagnoses: u64,
    pub abstentions: u64,
}
#[derive(Clone, Debug, Default, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DiagnosticEvaluation {
    pub synthetic: bool,
    pub representative: bool,
    pub held_out_origins: usize,
    pub counts: DiagnosticEvaluationCount,
    pub by_family: BTreeMap<String, DiagnosticEvaluationCount>,
    pub protocol_version: String,
}
pub fn diagnostic_evaluation_corpus() -> Result<Vec<DiagnosticEvaluationCase>, String> {
    serde_json::from_str(include_str!("../evaluation/diagnostics.json")).map_err(|e| e.to_string())
}
pub fn evaluate_diagnostics(
    rules: &[DiagnosticRule],
    ranker: &DiagnosticRanker,
    corpus: &[DiagnosticEvaluationCase],
) -> Result<DiagnosticEvaluation, String> {
    let mut origins = BTreeMap::new();
    let mut ids = BTreeSet::new();
    for case in corpus {
        if !ids.insert(&case.id)
            || !matches!(case.split.as_str(), "development" | "evaluation")
            || case.records.len() > 1000
        {
            return Err("Corpus diagnóstico inválido".into());
        }
        if origins
            .insert(&case.origin, &case.split)
            .is_some_and(|old| old != &case.split)
        {
            return Err("Origem compartilhada entre desenvolvimento e avaliação".into());
        }
    }
    let mut report = DiagnosticEvaluation {
        synthetic: true,
        representative: false,
        held_out_origins: origins
            .values()
            .filter(|s| s.as_str() == "evaluation")
            .count(),
        protocol_version: DIAGNOSTIC_VERSION.into(),
        ..Default::default()
    };
    for case in corpus.iter().filter(|c| c.split == "evaluation") {
        let mut summary = DiagnosticSummary::default();
        for (i, record) in case.records.iter().enumerate() {
            let mut facts = extract_diagnostic(record);
            for &feature in &case.derived_features {
                facts.add(feature, true);
            }
            summary.observe(
                DiagnosticReference {
                    event_ref: format!("{}:{i}", case.id),
                    event_id: i as i64,
                    timestamp: Some(i as i64),
                },
                facts.mask,
                facts.typed,
                facts.failure,
            );
        }
        let mut assessment = assess_diagnostic(&summary, rules);
        ranker.apply(&summary, &mut assessment);
        let family = case
            .expected
            .map(|d| d.family())
            .unwrap_or("benign_or_unknown");
        for count in [
            &mut report.counts,
            report.by_family.entry(family.into()).or_default(),
        ] {
            count.cases += 1;
            count.abstentions += u64::from(assessment.hypotheses.is_empty());
            if let Some(expected) = case.expected {
                count.eligible += 1;
                count.top_one += u64::from(
                    assessment
                        .hypotheses
                        .first()
                        .is_some_and(|h| h.diagnosis == expected),
                );
                count.top_three += u64::from(
                    assessment
                        .hypotheses
                        .iter()
                        .any(|h| h.diagnosis == expected),
                );
            } else {
                count.false_diagnoses += u64::from(!assessment.hypotheses.is_empty());
            }
        }
    }
    Ok(report)
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DiagnosticKnowledge {
    pub schema_version: u32,
    pub engine_version: String,
    pub rules: Vec<DiagnosticRule>,
    pub episodes: BTreeMap<String, DiagnosticContribution>,
    pub ranker: DiagnosticRanker,
    pub evaluation: DiagnosticEvaluation,
}
impl DiagnosticKnowledge {
    pub fn baseline() -> Result<Self, String> {
        let rules = diagnostic_rules();
        let ranker = DiagnosticRanker::default();
        let evaluation = evaluate_diagnostics(&rules, &ranker, &diagnostic_evaluation_corpus()?)?;
        Ok(Self {
            schema_version: DIAGNOSTIC_SCHEMA,
            engine_version: DIAGNOSTIC_VERSION.into(),
            rules,
            episodes: BTreeMap::new(),
            ranker,
            evaluation,
        })
    }
    pub fn revision(&self) -> String {
        digest(&serde_json::to_vec(self).expect("validated finite knowledge"))
    }
    pub fn validate(&self) -> Result<(), String> {
        if self.schema_version != DIAGNOSTIC_SCHEMA
            || self.engine_version != DIAGNOSTIC_VERSION
            || self.rules.len() != 14
            || self.episodes.len() > 4096
        {
            return Err("Base diagnóstica incompatível ou acima do orçamento".into());
        }
        let expected = diagnostic_rules()
            .iter()
            .map(|r| r.diagnosis)
            .collect::<BTreeSet<_>>();
        if self
            .rules
            .iter()
            .map(|r| r.diagnosis)
            .collect::<BTreeSet<_>>()
            != expected
        {
            return Err("Famílias diagnósticas ausentes ou repetidas".into());
        }
        for rule in &self.rules {
            rule.validate()?;
        }
        for (key, episode) in &self.episodes {
            episode.validate()?;
            if *key != format!("{}:{}", episode.origin, episode.episode) {
                return Err("Recibo público divergente".into());
            }
        }
        self.ranker.validate()?;
        let recomputed =
            evaluate_diagnostics(&self.rules, &self.ranker, &diagnostic_evaluation_corpus()?)?;
        if serde_json::to_value(&recomputed).map_err(|e| e.to_string())?
            != serde_json::to_value(&self.evaluation).map_err(|e| e.to_string())?
        {
            return Err("O relatório da base diagnóstica não corresponde à avaliação local".into());
        }
        if recomputed.counts.eligible == 0
            || recomputed.counts.top_three * 5 < recomputed.counts.eligible * 4
            || recomputed.counts.false_diagnoses > 0
            || recomputed
                .by_family
                .values()
                .any(|c| c.eligible > 0 && c.top_three * 5 < c.eligible * 4)
        {
            return Err("A base diagnóstica não passou nos controles reservados locais".into());
        }
        Ok(())
    }
    pub fn consolidate(contributions: Vec<DiagnosticContribution>) -> Result<Self, String> {
        if contributions.len() > 8192 {
            return Err("Mais de 8192 contribuições diagnósticas; revise a época".into());
        }
        let mut knowledge = Self::baseline()?;
        for contribution in contributions {
            contribution.validate()?;
            let key = format!("{}:{}", contribution.origin, contribution.episode);
            if let Some(old) = knowledge.episodes.get(&key) {
                if old.revision == contribution.revision && old.id != contribution.id {
                    return Err("Revisões concorrentes do mesmo recibo diagnóstico".into());
                }
                if old.revision >= contribution.revision {
                    continue;
                }
            }
            knowledge.episodes.insert(key, contribution);
        }
        if knowledge.episodes.len() > 4096 {
            return Err("Base diagnóstica atingiu 4096 episódios; revise a época".into());
        }
        // Cap each origin and reserve entire origins. A large installation
        // cannot win by publishing many repeats of the same incident.
        let mut by_origin = BTreeMap::<String, Vec<&DiagnosticContribution>>::new();
        for episode in knowledge.episodes.values() {
            if episode.labels.is_empty() {
                continue;
            }
            by_origin
                .entry(episode.origin.clone())
                .or_default()
                .push(episode);
        }
        if by_origin.len() >= 4 && by_origin.len() <= 32 {
            let held_out = by_origin
                .keys()
                .rev()
                .take(by_origin.len().div_ceil(4))
                .cloned()
                .collect::<BTreeSet<_>>();
            let mut train = Vec::new();
            let mut validation = Vec::new();
            let training_origins = by_origin.len() - held_out.len();
            for (origin, mut episodes) in by_origin {
                episodes.sort_by_key(|e| std::cmp::Reverse(e.revision));
                let reserved = held_out.contains(&origin);
                let budget = 2048
                    / if reserved {
                        held_out.len()
                    } else {
                        training_origins
                    };
                let mut admitted = 0;
                for e in episodes.into_iter().take(64) {
                    // Retain whole episodes and balance origins before fitting.
                    // Growing the history must not disable ranking simply by
                    // exceeding the bounded example budget.
                    if admitted + e.labels.len() > budget {
                        continue;
                    }
                    admitted += e.labels.len();
                    for label in &e.labels {
                        let Some(&base_score) = e.scores.get(&label.diagnosis) else {
                            continue;
                        };
                        let example = DiagnosticRankingExample {
                            episode: format!("{}:{}", e.origin, e.episode),
                            at: e.revision as i64,
                            diagnosis: label.diagnosis,
                            confirmed: label.confirmed,
                            features: e.features,
                            base_score,
                        };
                        if reserved {
                            validation.push(example);
                        } else {
                            train.push(example);
                        }
                    }
                }
            }
            if train.len() <= 2048 && validation.len() <= 2048 {
                let mut model = crate::diagnostic_ranker::fit(&train.iter().collect::<Vec<_>>());
                model.training_episodes = train
                    .iter()
                    .map(|e| &e.episode)
                    .collect::<BTreeSet<_>>()
                    .len();
                model.validation_episodes = validation
                    .iter()
                    .map(|e| &e.episode)
                    .collect::<BTreeSet<_>>()
                    .len();
                let mut families = BTreeMap::<&str, (usize, usize)>::new();
                let mut episode_gains = Vec::new();
                for id in validation
                    .iter()
                    .map(|e| &e.episode)
                    .collect::<BTreeSet<_>>()
                {
                    let group = validation
                        .iter()
                        .filter(|e| &e.episode == id)
                        .collect::<Vec<_>>();
                    let mut paired = false;
                    let mut gain = 0;
                    for a in group.iter().filter(|e| e.confirmed) {
                        for b in group.iter().filter(|e| !e.confirmed) {
                            let before = a.base_score > b.base_score;
                            let after = model.score(a.diagnosis, a.features, a.base_score)
                                > model.score(b.diagnosis, b.features, b.base_score);
                            paired = true;
                            gain += i32::from(after) - i32::from(before);
                            model.validation_pairs += 1;
                            model.baseline_correct += usize::from(before);
                            model.candidate_correct += usize::from(after);
                            let family = families.entry(a.diagnosis.family()).or_default();
                            family.0 += usize::from(before);
                            family.1 += usize::from(after);
                        }
                    }
                    if paired {
                        episode_gains.push(gain);
                    }
                }
                model.active = model.validation_pairs >= 8
                    && crate::diagnostic_ranker::consistent_ranking_gain(&episode_gains)
                    && model.candidate_correct > model.baseline_correct
                    && families.values().all(|(a, b)| b >= a);
                model.validate()?;
                knowledge.ranker = model;
            }
        }
        knowledge.evaluation = evaluate_diagnostics(
            &knowledge.rules,
            &knowledge.ranker,
            &diagnostic_evaluation_corpus()?,
        )?;
        knowledge.validate()?;
        Ok(knowledge)
    }
}
